def luhn_valid(s):
    if len(s) < 2:
        return False
    s = s.replace(" ", "")
    if not s.isdigit():
        return False
    total = 0
    for i in range(len(s)-1, -1, -2):
        digit = int(s[i])
        if i % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0
```

