def title_case(s):
    if not s:
        return ""

    words = s.split()
    result = []

    for word in words:
        # Si le mot est un petit mot, on le conserve comme tel
        if word.lower() in ["a", "an", "the", "of", "and", "to"]:
            result.append(word)
        else:
            # Sinon, on met la première lettre en majuscule et les autres en minuscules
            result.append(word[0].upper() + word[1:].lower())

    return ' '.join(result)
```
